/**
 * Atlaso memory — OpenCode plugin (the npm package main + default export).
 *
 * The automatic memory loop, in pure TypeScript (bun-native, no Python). It owns
 * NO memory logic: it only does HTTP to the brain `/v1/*` via the shared, tool-
 * agnostic `lib/` (copied from the Cursor connector). The engine — retrieval,
 * the conflict gate, the worth-keeping judgment — stays on the server. This is
 * the IP thin-client rule, in an OpenCode plugin.
 *
 * The `config` hook adds the Atlaso MCP entry at load time (lib/mcp_entry.ts).
 * Two hooks make the loop:
 *   • "chat.message"      → recall relevant memory and inject it as a synthetic
 *                           text part BEFORE the model responds (auto-recall).
 *   • "event"/session.idle → capture the user's statement to memory when the
 *                           turn finishes (auto-capture).
 *
 * EVERYTHING is FAIL-OPEN: a hook error must never break an OpenCode turn, so
 * each hook body is wrapped in try/catch and the loop degrades to a no-op.
 *
 * Recall injection (verified live, opencode 1.17.x): pushing a SCHEMA-VALID
 * synthetic text part onto chat.message `output.parts` injects AI-visible context —
 * the model reads it and answers from it. OpenCode PERSISTS + strictly validates the
 * part (id must be `prt_*`, messageID must be this turn's real `msg_*`), so we derive
 * both from `output.message` and only ever ADD to the array. Fail-open: if there's no
 * real message id we SKIP injecting (a malformed part would throw and break the turn).
 */
import { createHash } from "node:crypto";
import type { Hooks, Plugin } from "@opencode-ai/plugin";
import type { Part } from "@opencode-ai/sdk";

import { depositDetailed, loadAuth, recall, type DepositItem } from "../lib/atlaso";
import { ambientCredentialCurrent, ambientRoom, ambientStart, withAmbient } from "../lib/ambient";
import { recordSkip, within } from "../lib/deadline";
import { drainIfPending } from "../lib/drain";
import { enqueue, promote, quarantine, resolveStaged, settle, stage, unstage } from "../lib/outbox";
import { markStatsSent, pendingCaptureStats, recordDepositResults, recordGate } from "../lib/capture_stats";
import { buildContent, classifyScope, heuristicPolarity, scrub, shouldDeposit } from "../lib/capture";
import { resolveCredential } from "../lib/credential";
import { maybeAutoconnect } from "../lib/connect";
import { online } from "../lib/entitlement";
import { log } from "../lib/log";
import { mcpEntryPathFor, registerAtlasoMcp } from "../lib/mcp_entry";
import { projectKey, projectResolution } from "../lib/project";
import { renderBlock } from "../lib/render";

const TOOL = "opencode";
const RECALL_LIMIT = 5;
/** OpenCode awaits chat.message before the model call: the brain round trip (entitlement,
 *  credential, recall) gets this much, then the turn goes ahead without memory. The idle
 *  capture's await is bounded too; its work finishes in the background (rung "hooks never
 *  hang"). */
const RECALL_NETWORK_MS = 2000;
const IDLE_CAPTURE_MS = 8000;

/** Deterministic idempotency key, so a re-deposit of the same statement collapses
 *  to ONE memory server-side. Scope + project key are folded in so the SAME
 *  content captured in a DIFFERENT project keeps its own attribution (matches the
 *  Cursor/Claude-Code connectors + the Python client). */
function clientId(content: string, scope: string, project: string | null): string {
  return createHash("sha256").update(`${scope} ${project ?? ""} ${content}`).digest("hex").slice(0, 32);
}

/** Join this turn's REAL user text from a chat.message output — only `type:"text"`
 *  parts that are NOT synthetic (so we never echo our own injected block back). */
function userTextFrom(parts: unknown): string {
  if (!Array.isArray(parts)) return "";
  const out: string[] = [];
  for (const p of parts as any[]) {
    if (p && p.type === "text" && typeof p.text === "string" && !p.synthetic) out.push(p.text);
  }
  return out.join("\n").trim();
}

/** A SCHEMA-VALID synthetic TextPart carrying the recalled block. OpenCode SAVES
 *  injected parts and validates them strictly: `id` must start with `prt_` and
 *  `messageID` must be THIS turn's real `msg_*` — a malformed part throws and BREAKS
 *  the turn (verified live on opencode 1.17.x). So we derive both from
 *  `output.message`; the caller only calls this when a real message id is present. */
function memoryPart(block: string, message: { id: string; sessionID: string }): Part {
  return {
    id: `prt_${createHash("sha256").update(`${message.id}:${block}`).digest("hex").slice(0, 24)}`,
    sessionID: message.sessionID,
    messageID: message.id,
    type: "text",
    text: block,
    synthetic: true, // marks it as injected — kept out of the user transcript
  };
}

export const AtlasoMemory: Plugin = async ({ directory, worktree }): Promise<Hooks> => {
  // Detached browser-authorize on first run; no-op once this machine is linked.
  try {
    maybeAutoconnect(TOOL);
  } catch {
    /* fail-open: never let connect setup break plugin init */
  }

  // Per-session pending capture: the user's statement, saved at chat.message and
  // deposited on session.idle (which carries only the sessionID, not the text).
  const pending = new Map<string, { user: string }>();
  // OpenCode has no SessionStart output. Deliver on the first usable chat message
  // per session in this plugin lifetime, before the model sees that message.
  const ambientAttempted = new Set<string>();

  // Resolve the project ONCE at init (the plugin's directory is stable for the
  // session); null → personal-only scope.
  const project = projectKey(directory || worktree) || undefined;

  /** The session.idle capture (bounded by the caller's await; see IDLE_CAPTURE_MS). */
  async function captureIdle(event: any): Promise<void> {
    try {
      const sessionID: string | undefined = (event as any)?.properties?.sessionID;
      if (!sessionID) return;
      const p = pending.get(sessionID);
      if (!p) return;
      pending.delete(sessionID); // one capture per stashed statement

      const user = p.user;
      // Counter records EVERY gate evaluation (content-free; lab 85a5c41b).
      const scrubbed = scrub(user)[0];
      // Tri-state project attribution (mirrors the Python client core.py): resolve
      // a key only when the scope is "project" — 'ok' tags the key, 'none' ($HOME
      // etc.) downgrades to personal, 'unknown' (garbage: plugin/cache dir, error)
      // keeps scope:project with a bare "project-unknown" marker, never a key.
      let scope = classifyScope(user);
      let pk: string | null = null;
      let projectUnknown = false;
      if (scope === "project") {
        const { status, key } = projectResolution(directory || worktree);
        if (status === "none") scope = "personal";
        else if (status === "unknown") projectUnknown = true;
        else pk = key; // 'ok'
      }
      const preContent = buildContent(scrubbed, "");
      const dedupeKey = preContent
        ? clientId(preContent, scope, scope === "project" ? pk : null)
        : null;
      const [gateOk, gateReason] = shouldDeposit(user);
      await recordGate(gateReason, { turnKey: dedupeKey });
      if (!gateOk) {
        log("capture", "skip (gate)");
        return;
      }
      const auth = loadAuth(); // local file read, no network
      if (!auth) return; // online-first: a signed-out device keeps nothing

      const content = preContent; // assistant omitted in v1 (see TODO)
      if (!content) return;
      const tags = ["opencode", "auto", `pol-hint:${heuristicPolarity(user)}`, `scope:${scope}`];
      if (projectUnknown) tags.push("project-unknown"); // unattributed → provenance marker, no key
      if (pk) tags.push(`project:${pk}`);

      const item: DepositItem = {
        client_id: clientId(content, scope, scope === "project" ? pk : null),
        text: content,
        polarity: "open",
        evidence_grade: "anecdotal",
        scope_note: null,
        tags,
      };
      // WRITE-AHEAD, FIRST, INTO THE STAGED AREA: the turn is on disk (fsynced, atomic rename)
      // before any network call, entitlement and credential included. The idle await is bounded
      // (IDLE_CAPTURE_MS) and OpenCode may quit while a slow entitlement is still pending; the
      // turn then stays staged instead of being lost with the in-memory stash (CodeRedTeam
      // 580c16b5). Staged is NOT drainable: a chat.message drain in this same process while we
      // await entitlement must not upload a turn whose verdict may be local-only (CodeRedTeam
      // e632b415). Only this capture's own allow verdict promotes it. Idempotent on client_id.
      const staged = stage(TOOL, item);
      if (!(await online(auth, { tool: TOOL, deviceId: auth.device_id ?? null }))) {
        // Local-only is a decision: drop the staged turn (no local store in this connector,
        // as before this rung) and any staged turn a dead OpenCode process left undecided.
        unstage(TOOL, item.client_id);
        resolveStaged(TOOL, null);
        log("capture", "skip (not cloud-linked: local-only)");
        return;
      }
      const cred = await resolveCredential(TOOL);
      if (!cred) {
        unstage(TOOL, item.client_id);
        resolveStaged(TOOL, null);
        log("capture", "skip (local-only: no tool credential)");
        return;
      }
      // Allowed: record the verdict on the turn and make it drainable, then settle orphans.
      const allow = { at: Date.now(), by: "capture" };
      if (staged) promote(TOOL, item.client_id, allow);
      else enqueue(TOOL, item, allow);
      resolveStaged(TOOL, allow);

      const stats = pendingCaptureStats();
      const { ok, results, status } = await depositDetailed(cred, [item], stats ?? undefined);
      if (ok) {
        if (stats) await markStatsSent(stats);
        await recordDepositResults(results);
        const verdict = results.find((r) => r.client_id === item.client_id);
        if (verdict && verdict.status !== "invalid") {
          settle(TOOL, item.client_id);
          unstage(TOOL, item.client_id); // a half-done promotion: the brain has it
        }
        else if (verdict)
          quarantine(TOOL, { client_id: item.client_id, item, enqueued_at: Date.now(), attempts: 1 },
                     `server rejected: ${verdict.status}`);
      }
      log("capture", `saved=${ok}${ok ? "" : ` queued (${status || "transport"})`} scope=${scope} session=${sessionID}`);
      // Opportunistic catch-up between turns; cheap no-op on an empty queue.
      await drainIfPending(TOOL, cred);
    } catch (e) {
      log("capture", `error ${e} (queued)`); // fail open — the memory is on disk
    }
  }

  return {
    /**
     * MCP TOOLS. OpenCode hands every plugin the merged config before any MCP server starts;
     * we add the `Atlaso` MCP entry from the file `atlaso setup` dropped next to this plugin,
     * unless the user's own config already has an `Atlaso` entry (theirs wins, even when it is
     * turned off). opencode.json itself is never written. See lib/mcp_entry.ts.
     */
    config: async (cfg) => {
      try {
        const r = registerAtlasoMcp(cfg, mcpEntryPathFor(import.meta.url));
        if (r !== "added") log("mcp", `config ${r}`);
      } catch (e) {
        log("mcp", `config error ${e}`); // fail open: OpenCode starts without the Atlaso tools
      }
    },

    /**
     * AUTO-RECALL. On each new user message, recall relevant memory and unshift it
     * as a synthetic text part so the model sees it before responding. Cloud-gated
     * (free plan = 1 active tool/device; the brain doesn't enforce it — we do).
     */
    "chat.message": async (input, output) => {
      if (process.env.ATLASO_EXTRACTING) return; // never recall inside our own enrichment
      try {
        if (!output || !Array.isArray(output.parts)) return; // shape changed → no-op
        const userText = userTextFrom(output.parts);
        if (!userText) return;

        const auth = loadAuth();
        if (!auth) return; // online-first: not linked → nothing to recall
        // remember this turn's user statement for capture at session.idle (the idle
        // handler runs its own cloud gate before anything leaves the machine)
        pending.set(input.sessionID, { user: userText });

        const message = (output as { message?: { id?: string; sessionID?: string } }).message;
        const first = !!message?.id && !ambientAttempted.has(input.sessionID);
        if (first) ambientAttempted.add(input.sessionID); // before await, including concurrent turns
        const credential = resolveCredential(TOOL).catch(() => null);
        const orientation = first
          ? ambientStart(auth, TOOL, project ?? null, RECALL_NETWORK_MS, credential)
          : Promise.resolve(null);
        const cloud = (async () => {
          if (!(await online(auth, { tool: TOOL, deviceId: auth.device_id ?? null }))) return null; // local-only this turn
          const cred = await credential;
          if (!cred) return null; // no cloud this run
          const results = await recall(cred, userText, RECALL_LIMIT, project, input.sessionID);
          return { cred, results };
        })();
        const [raced, fetchedAmbient] = await Promise.all([within(cloud, RECALL_NETWORK_MS, null), orientation]);
        const ambient = fetchedAmbient && ambientCredentialCurrent(auth, TOOL, await credential)
          ? fetchedAmbient : null;
        if (!raced.done) {
          // Too slow: the turn proceeds without recall. The late answer is dropped, never
          // injected after this hook has returned.
          recordSkip(TOOL, "recall", "network_deadline");
          log("recall", "skip (network deadline)");
        }
        const { cred, results } = (raced.done && raced.value) || { cred: null, results: [] };

        // THE RECOVERY PATH. If a previous session ended while the brain was down
        // (or mid-deploy, or the laptop was offline), those memories are still in
        // the outbox. Catch up in the BACKGROUND: the model call never waits on it.
        // Turns a quit OpenCode left STAGED (no verdict) are decided here with this hook's own
        // allow verdict, re-evaluated just now; a live capture's staged turn is left to it.
        if (cred) {
          resolveStaged(TOOL, { at: Date.now(), by: "chat_message" }, { adoptLegacy: true });
          void drainIfPending(TOOL, cred).catch(() => {});
        }

        const block = withAmbient(ambient, renderBlock(results, { budget: ambientRoom(ambient) }));
        // OpenCode persists + strictly validates injected parts, so we can only build
        // a schema-valid one when THIS turn's real message id (msg_*) is present on
        // output.message. If it's missing, skip injecting (never crash the turn).
        if (block && message?.id) {
          output.parts.unshift(memoryPart(block, { id: message.id, sessionID: message.sessionID || input.sessionID }));
          log("recall", `injected n=${results.length} session=${input.sessionID}`);
        } else if (block) {
          log("recall", "skip-inject (no message id on output.message)");
        }
      } catch (e) {
        log("recall", "error"); // fail open — memory must never break a turn
      }
    },

    /**
     * AUTO-CAPTURE. session.idle fires at end of turn and carries ONLY the
     * sessionID — so we deposit the user statement we stashed at chat.message.
     * Write-only; injects no context. Cloud-gated + secret-scrubbed client-side.
     *
     * TODO(enrichment): session.idle has no assistant text, so v1 captures the
     * user statement alone (the core value). A follow-up can fetch the turn's
     * assistant reply via the opencode SDK client and enrich buildContent(user,
     * assistant) before depositing.
     */
    event: async ({ event }) => {
      if (process.env.ATLASO_EXTRACTING) return; // never capture our own enrichment
      if (event?.type === "session.deleted") {
        const id = (event as any).properties?.info?.id;
        if (typeof id === "string") {
          ambientAttempted.delete(id);
          pending.delete(id);
        }
        return;
      }
      if (event?.type !== "session.idle") return;
      const raced = await within(captureIdle(event), IDLE_CAPTURE_MS, undefined);
      if (!raced.done) recordSkip(TOOL, "capture", "deadline"); // still finishing in the background
    },
  };
};

export default AtlasoMemory;
